#!/bin/bash
# Uninstall script for Eclipse IDE for Java EE Developers
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Eclipse IDE for Java EE Developers..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Eclipse IDE for Java EE Developers if running..."
pkill -f "Eclipse IDE for Java EE Developers" 2>/dev/null || true

# Kill application with bundle ID epp.package.jee if running
echo "Stopping application with bundle ID epp.package.jee if running..."
killall -9 "epp.package.jee" 2>/dev/null || true

# Remove /Applications/Eclipse.app
echo "Removing /Applications/Eclipse.app..."
if [ -d "/Applications/Eclipse.app" ]; then
    rm -rf "/Applications/Eclipse.app" 2>/dev/null || true
elif [ -f "/Applications/Eclipse.app" ]; then
    rm -f "/Applications/Eclipse.app" 2>/dev/null || true
fi

# Remove /Applications/{'target': 'Eclipse JEE.app'}
echo "Removing /Applications/{'target': 'Eclipse JEE.app'}..."
if [ -d "/Applications/{'target': 'Eclipse JEE.app'}" ]; then
    rm -rf "/Applications/{'target': 'Eclipse JEE.app'}" 2>/dev/null || true
elif [ -f "/Applications/{'target': 'Eclipse JEE.app'}" ]; then
    rm -f "/Applications/{'target': 'Eclipse JEE.app'}" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/org.eclipse.platform.ide
echo "Removing $HOME/Library/Caches/org.eclipse.platform.ide..."
if [ -d "$HOME/Library/Caches/org.eclipse.platform.ide" ]; then
    rm -rf "$HOME/Library/Caches/org.eclipse.platform.ide" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/org.eclipse.platform.ide" ]; then
    rm -f "$HOME/Library/Caches/org.eclipse.platform.ide" 2>/dev/null || true
fi

# Remove $HOME/Library/Cookies/org.eclipse.platform.ide.binarycookies
echo "Removing $HOME/Library/Cookies/org.eclipse.platform.ide.binarycookies..."
if [ -d "$HOME/Library/Cookies/org.eclipse.platform.ide.binarycookies" ]; then
    rm -rf "$HOME/Library/Cookies/org.eclipse.platform.ide.binarycookies" 2>/dev/null || true
elif [ -f "$HOME/Library/Cookies/org.eclipse.platform.ide.binarycookies" ]; then
    rm -f "$HOME/Library/Cookies/org.eclipse.platform.ide.binarycookies" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/org.eclipse.platform.ide.plist
echo "Removing $HOME/Library/Preferences/org.eclipse.platform.ide.plist..."
if [ -d "$HOME/Library/Preferences/org.eclipse.platform.ide.plist" ]; then
    rm -rf "$HOME/Library/Preferences/org.eclipse.platform.ide.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/org.eclipse.platform.ide.plist" ]; then
    rm -f "$HOME/Library/Preferences/org.eclipse.platform.ide.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/org.eclipse.platform.ide.savedState
echo "Removing $HOME/Library/Saved Application State/org.eclipse.platform.ide.savedState..."
if [ -d "$HOME/Library/Saved Application State/org.eclipse.platform.ide.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/org.eclipse.platform.ide.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/org.eclipse.platform.ide.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/org.eclipse.platform.ide.savedState" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
